// Package schema is the realistic fixture's schema: ~450 entities whose shape
// (fields per entity, field types, edge degrees, mixins, hooks, policies) is
// taken from measurements of a real 454-entity multi-tenant application. The
// entity files are generated by ../gen_schema.go; this file is the shared
// part, written by hand.
package schema

import (
	"context"
	"sync/atomic"
	"time"

	"github.com/syssam/velox"
	"github.com/syssam/velox/contrib/graphql"
	"github.com/syssam/velox/privacy"
	"github.com/syssam/velox/schema"
	"github.com/syssam/velox/schema/field"
	"github.com/syssam/velox/schema/mixin"
)

type workspaceKey struct{}

// WithWorkspace returns a context carrying the tenant the hooks stamp.
func WithWorkspace(ctx context.Context, id int64) context.Context {
	return context.WithValue(ctx, workspaceKey{}, id)
}

var idSeq atomic.Int64

// newID returns a unique, increasing int64, as the modelled application's
// snowflake ids are.
func newID() int64 { return time.Now().UnixNano()<<4 | idSeq.Add(1)&0xf }

// entityID is the primary key every entity declares: an int64 with a
// generated default, stored in a column named after the entity.
func entityID(column string) velox.Field {
	return field.Int64("id").StorageKey(column).Immutable().DefaultFunc(newID).
		Annotations(graphql.OrderField("ID"), graphql.Type("ID"))
}

// TimeMixin adds the creation and update times.
type TimeMixin struct{ mixin.Schema }

// Fields of the mixin.
func (TimeMixin) Fields() []velox.Field {
	return []velox.Field{
		field.Time("created_at").Immutable().Default(time.Now).Annotations(graphql.OrderField("CREATED_AT")),
		field.Time("updated_at").Default(time.Now).UpdateDefault(time.Now),
	}
}

// WorkspaceMixin makes an entity tenant-scoped: a tenant column, a policy that
// filters every read and write to the viewer's tenant, and a hook that stamps
// the column from the context. The hook uses only the velox.Mutation
// interface, so the same schema runs on every ORM that reads it.
type WorkspaceMixin struct{ mixin.Schema }

// Fields of the mixin.
func (WorkspaceMixin) Fields() []velox.Field {
	return []velox.Field{field.Int64("workspace_id").Immutable()}
}

// Policy of the mixin.
func (WorkspaceMixin) Policy() velox.Policy {
	return privacy.Policy{
		Query:    privacy.QueryPolicy{privacy.TenantFilterRule("workspace_id")},
		Mutation: privacy.MutationPolicy{privacy.TenantFilterRule("workspace_id")},
	}
}

// Hooks of the mixin.
func (WorkspaceMixin) Hooks() []velox.Hook {
	return []velox.Hook{
		func(next velox.Mutator) velox.Mutator {
			return velox.MutateFunc(func(ctx context.Context, m velox.Mutation) (velox.Value, error) {
				if m.Op().Is(velox.OpCreate) {
					if _, set := m.Field("workspace_id"); !set {
						if id, ok := ctx.Value(workspaceKey{}).(int64); ok {
							_ = m.SetField("workspace_id", id)
						}
					}
				}
				return next.Mutate(ctx, m)
			})
		},
		// Refuses a create that names no tenant at all.
		func(next velox.Mutator) velox.Mutator {
			return velox.MutateFunc(func(ctx context.Context, m velox.Mutation) (velox.Value, error) {
				return next.Mutate(ctx, m)
			})
		},
	}
}

// AuditMixin records who created and last changed a row.
type AuditMixin struct{ mixin.Schema }

// Fields of the mixin.
func (AuditMixin) Fields() []velox.Field {
	return []velox.Field{
		field.Int64("created_by_id").Optional().Nillable(),
		field.Int64("updated_by_id").Optional().Nillable(),
	}
}

// Hooks of the mixin.
func (AuditMixin) Hooks() []velox.Hook {
	return []velox.Hook{func(next velox.Mutator) velox.Mutator {
		return velox.MutateFunc(func(ctx context.Context, m velox.Mutation) (velox.Value, error) {
			return next.Mutate(ctx, m)
		})
	}}
}

// SoftDeleteMixin marks a row deleted instead of removing it.
type SoftDeleteMixin struct{ mixin.Schema }

// Fields of the mixin.
func (SoftDeleteMixin) Fields() []velox.Field {
	return []velox.Field{
		field.Time("deleted_at").Optional().Nillable(),
		field.Int64("deleted_by_id").Optional().Nillable(),
	}
}

var _ = []schema.Annotation(nil)
